(() => {
  const byId = Object.fromEntries(window.CURRICULUM.map(module => [module.id, module]));
  const lesson = (number, title, body) => `<section class="lesson"><div class="lesson-number">${number}</div><div><h3>${title}</h3>${body}</div></section>`;
  const chapter = (days, hours, outcome, items, checks) => `<div class="course-intro"><div><span>${days} study days</span><strong>${hours}</strong><small>읽기 · 구현 · 검증 · 실험을 포함한 권장 시간</small></div><p><b>Exit criterion.</b> ${outcome}</p></div><div class="study-plan"><h3>학습 흐름</h3><div class="day-grid">${items.map((x, i) => `<article><span>Step ${i + 1}</span><b>${x[0]}</b><p>${x[1]}</p></article>`).join("")}</div></div>${items.map((x, i) => lesson(String(i + 1).padStart(2, "0"), x[0], x[2])).join("")}<section class="assessment"><h3>완료 기준</h3><div class="assessment-grid">${checks.map(x => `<div><b>${x[0]}</b><p>${x[1]}</p></div>`).join("")}</div></section>`;
  const attach = (id, days, hours, outcome, items, checks, walkthrough) => { byId[id].longform = chapter(days, hours, outcome, items, checks); byId[id].walkthrough = walkthrough; };

  byId.foundations.longform += lesson("00.6a", "GPU benchmark 코드를 한 줄씩 읽기", `<p>GPU benchmark는 CPU에서 Python 함수가 돌아간 시간을 재는 일이 아닙니다. CPU는 GPU에 실행 요청을 넣고 GPU가 끝나기 전에 다음 Python 줄로 갈 수 있습니다. host wall-clock만 쓰면 GPU 계산 시간이 아니라 CPU가 요청을 queue에 넣는 시간만 재게 됩니다.</p><pre class="lesson-code"><code>torch.cuda.synchronize()  # 이전 GPU 작업을 끝낸다<br>samples = []  # 여러 관측치를 담는다<br>for _ in range(repeats):  # 같은 실험을 반복한다<br>start = torch.cuda.Event(enable_timing=True)  # 시작 표지판<br>end = torch.cuda.Event(enable_timing=True)  # 끝 표지판<br>start.record(); fn(); end.record()  # 같은 stream의 순서<br>end.synchronize()  # GPU가 끝 event까지 오기를 기다린다<br>samples.append(start.elapsed_time(end))  # GPU ms를 기록한다<br>samples.sort()  # p50/p95 계산을 위해 정렬한다</code></pre><ol><li><b>synchronize:</b> warm-up이나 이전 실험이 남아 있지 않게 합니다.</li><li><b>samples:</b> 시간은 흔들리므로 한 번이 아니라 분포를 모읍니다.</li><li><b>Event:</b> CPU 시계가 아니라 GPU stream 위의 두 표지판 사이 시간을 잽니다.</li><li><b>record → fn → record:</b> 같은 stream은 순서를 보장하므로 두 event 사이에 fn의 GPU 작업이 위치합니다.</li><li><b>end.synchronize:</b> event 시간이 준비될 때까지 CPU가 기다립니다.</li></ol><div class="task"><b>실습</b><p>동일 GEMM을 (a) 동기화 없는 <code>time.perf_counter</code>, (b) 매 반복 <code>torch.cuda.synchronize</code>, (c) CUDA event로 재고, 세 결과가 다른 이유를 CPU queue와 GPU stream 그림으로 설명하세요.</p></div>`);
  byId.foundations.walkthrough = {title:"Reference code line by line",intro:"이 함수는 Tensor의 layout과 dtype을 확인하는 검사 도구입니다.",lines:[{line:"def describe(x):",explanation:"Tensor 하나를 받아 관찰 결과를 dictionary로 반환합니다."},{line:'"shape": tuple(x.shape),',explanation:"각 axis의 길이입니다. [B,T,D]=[2,128,64]라면 (2,128,64)입니다."},{line:'"stride": x.stride(),',explanation:"index를 하나 올릴 때 storage에서 몇 원소를 건너뛰는지입니다."},{line:'"bytes": x.numel() * x.element_size(),',explanation:"논리 원소 수와 원소당 byte를 곱합니다."},{line:'"contiguous": x.is_contiguous(),',explanation:"기본 연속 layout인지 확인합니다. false는 오류가 아니지만 내부 복사가 생길 수 있습니다."}]};
  byId.attention.walkthrough = {title:"Reference code line by line",intro:"Attention은 score를 만들고, 허용된 score만 확률로 바꾸며, 그 확률로 value를 가중 평균합니다.",lines:[{line:"scale = q.size(-1) ** -0.5",explanation:"Dk에서 1/√Dk를 만들어 score 분산을 제어합니다."},{line:"scores = q @ k.transpose(-2, -1) * scale",explanation:"모든 query/key pair의 내적을 계산해 [B,Tq,Tk] score를 만듭니다."},{line:'scores = scores.masked_fill(mask, float("-inf"))',explanation:"금지 위치를 −∞로 만들어 softmax 후 확률이 0이 되게 합니다."},{line:"probs = torch.softmax(scores.float(), dim=-1).to(q.dtype)",explanation:"softmax의 지수와 합은 FP32에서 계산합니다."},{line:"return probs @ v",explanation:"확률 행이 value 행을 가중 평균해 [B,Tq,Dv]를 만듭니다."}]};

  attach("transformer","12","24–32 hours","token ID부터 logits까지의 tensor 경로를 설명하고 작은 decoder-only Transformer를 reference와 비교할 수 있다.",[["Embedding","정수 ID가 vector가 되는 과정","<p>Token ID는 단어가 아니라 embedding table의 행 번호입니다. E∈ℝ<sup>V×d</sup>에서 E[id]를 꺼내면 d차원 vector가 됩니다. [B,T] ID는 [B,T,d] hidden state가 됩니다.</p><div class=\"equation\">h₀ = embedding(ids) + position information</div><p>logits는 확률이 아니라 vocabulary의 각 token에 대한 정규화 전 점수입니다.</p>"],["Residual and norm","정보와 gradient가 block을 지나는 길","<p><code>x = x + f(norm(x))</code>에서 norm은 f의 입력만 안정화하고 x는 원래 정보를 보존합니다. identity path가 있어 깊은 block도 작은 수정부터 학습할 수 있습니다.</p><pre class=\"lesson-code\"><code>rms = x.pow(2).mean(dim=-1, keepdim=True).add(eps).rsqrt()<br>return x * rms * weight</code></pre><p><code>keepdim=True</code>가 없으면 [B,T] RMS를 [B,T,d] x의 마지막 축에 broadcast할 수 없습니다.</p>"],["RoPE","position과 cache offset","<p>RoPE는 인접 feature 두 개를 2D 좌표로 보고 position별 각도로 회전합니다. Q와 K의 내적은 상대 위치 차이를 반영합니다. V에는 보통 적용하지 않습니다.</p><pre class=\"lesson-code\"><code>def apply_rope(x, cos, sin):<br>&nbsp;&nbsp;return x * cos + rotate_half(x) * sin</code></pre><div class=\"warning\"><b>중요:</b><p>decode에서 새 token position은 0이 아니라 cache에 저장된 token 수입니다.</p></div>"],["MLP and generation","token-wise 변환과 결정론적 debug","<p>Attention은 token 사이 정보를 섞고 MLP는 각 token 안의 feature를 바꿉니다. SwiGLU는 gate와 value projection을 곱합니다. 처음에는 argmax만 써서 같은 입력에 같은 결과가 나게 하세요.</p><pre class=\"lesson-code\"><code>gate = F.silu(self.gate(x))<br>value = self.up(x)<br>x = self.down(gate * value)<br>next_id = logits[:, -1].argmax(-1, keepdim=True)</code></pre><div class=\"task\"><b>실습</b><p>embedding, norm, Q/K/V, attention output, MLP output, logits의 shape와 max error를 layer별로 출력해 reference와 비교하세요.</p></div>"]],[["Build","RMSNorm·RoPE·SwiGLU·pre-norm block을 구현한다."],["Trace","각 intermediate tensor shape와 dtype을 표로 만든다."],["Verify","logits와 greedy IDs를 reference와 비교한다."],["Explain","residual과 position offset을 설명한다."]],{title:"Reference code line by line",intro:"이 block은 attention과 MLP의 보정값을 residual stream에 순서대로 더합니다.",lines:[{line:"a, cache = self.attn(self.norm1(x), cache, pos)",explanation:"첫 norm 결과를 attention에 주고 attention output과 갱신된 cache를 받습니다."},{line:"x = x + a",explanation:"attention 보정값을 원래 stream에 더합니다. 두 tensor shape가 같아야 합니다."},{line:"x = x + self.mlp(self.norm2(x))",explanation:"업데이트된 x를 다시 norm한 뒤 MLP 보정값을 더합니다."},{line:"return x, cache",explanation:"다음 layer에 새 hidden state와 이 layer cache를 넘깁니다."}]});

  attach("multihead","7","14–20 hours","MHA·MQA·GQA의 head layout과 mapping을 구현하고 KV head 수가 serving memory를 어떻게 바꾸는지 계산할 수 있다.",[["Head geometry","model width를 head axis와 head dimension으로 분해","<p>d_model=4096, H=32이면 D=128입니다. projection 결과 [B,T,4096]을 [B,T,32,128]로 바꾸고 attention layout [B,32,T,128]로 transpose합니다.</p><pre class=\"lesson-code\"><code>x = x.view(B, T, heads, d_head).transpose(1, 2)</code></pre><p>transpose는 대개 stride만 바꾸는 view입니다. 이후 kernel이 contiguous layout을 요구할 때 copy가 생길 수 있습니다.</p>"],["MHA, MQA, GQA","무엇을 공유하는가","<table><thead><tr><th>방법</th><th>Query heads</th><th>KV heads</th></tr></thead><tbody><tr><td>MHA</td><td>H</td><td>H</td></tr><tr><td>MQA</td><td>H</td><td>1</td></tr><tr><td>GQA</td><td>H</td><td>Hkv</td></tr></tbody></table><p>H=32,Hkv=8인 GQA의 KV cache payload는 MHA의 1/4입니다. Query heads까지 1/4가 되는 것은 아닙니다.</p><div class=\"equation\">KV memory ratio = H<sub>kv</sub> / H<sub>q</sub></div>"],["Mapping","어느 query가 어느 KV를 보는가","<pre class=\"lesson-code\"><code>group_size = num_q_heads // num_kv_heads<br>kv_head = query_head // group_size</code></pre><p>Hq=8,Hkv=2이면 q0–q3은 kv0, q4–q7은 kv1을 봅니다. reference에서 K/V를 실제로 반복하면 이해는 쉽지만 memory 절감 효과는 사라집니다.</p>"],["Serving trade-off","decode bandwidth와 quality","<p>새 query 하나는 길이 T의 K/V를 읽습니다. KV head가 적으면 읽는 bytes가 줄어 bandwidth 압력이 낮아질 수 있습니다. 하지만 quality가 바뀔 수 있으므로 같은 quality constraint에서 benchmark해야 합니다.</p><div class=\"task\"><b>실습</b><p>Hq=4,Hkv=2에서 GQA output과 expanded-KV reference가 같은지 test하고 MHA/MQA/GQA cache bytes 표를 만드세요.</p></div>"]],[["Shape","split/merge의 shape와 stride를 설명한다."],["Correctness","GQA와 expanded-KV reference를 비교한다."],["Memory","세 방식의 KV bytes를 계산한다."],["Judgment","복제가 왜 serving 최적화가 아닌지 설명한다."]],{title:"Reference code line by line",intro:"이 구현은 mapping을 보이기 위해 K/V를 실제로 반복합니다. production에서는 이 복제를 피합니다.",lines:[{line:"groups = num_q_heads // num_kv_heads",explanation:"한 KV head를 몇 query head가 공유하는지 계산합니다."},{line:"k = k.repeat_interleave(groups, dim=1)",explanation:"K를 query head 수만큼 반복합니다. 이 때문에 memory를 절약하지 못합니다."},{line:"v = v.repeat_interleave(groups, dim=1)",explanation:"K와 같은 mapping으로 V도 반복해야 합니다."},{line:"out = out.transpose(1, 2).reshape(B, Tq, -1)",explanation:"[H,D]를 하나의 model-width axis로 합칩니다."}]});

  attach("kvcache","10","20–28 hours","prefill과 decode를 구분하고 cached decoder가 uncached decoder와 logits/token ID까지 일치함을 보일 수 있다.",[["Reuse","왜 K/V만 저장하는가","<p>과거 token의 K/V는 다음 decode step에서 바뀌지 않습니다. 새 token은 query 하나만 새로 만들고 과거 K/V 전체를 읽습니다. 이전 query는 다시 쓰이지 않으므로 저장하지 않습니다.</p><div class=\"equation\">prefill: Q[1:T], K[1:T], V[1:T]<br>decode: Q[t] + cached K[1:t], V[1:t]</div>"],["Memory","cache bytes를 직접 세기","<p>한 token·한 layer에는 K와 V 두 개가 있고 각각 Hkv×D 원소입니다. 원소당 bytes=e이면:</p><div class=\"equation\">bytes = 2 × layers × tokens × H<sub>kv</sub> × D × e × active sequences</div><p>이 값은 allocator metadata, alignment, workspace, model weights를 포함하지 않습니다.</p>"],["Append","capacity와 valid length 분리","<pre class=\"lesson-code\"><code>start = cache.length<br>end = start + k_new.size(-2)<br>if end &gt; cache.k.size(-2): raise RuntimeError(\"capacity exceeded\")<br>cache.k[..., start:end, :].copy_(k_new)<br>cache.v[..., start:end, :].copy_(v_new)<br>cache.length = end</code></pre><p><code>torch.cat</code>를 매 token마다 쓰면 새 storage를 반복 생성해 preallocated cache의 목적을 잃습니다.</p>"],["Equivalence","cached/uncached test","<p>전체 prefix를 다시 넣는 느린 방식과 prefill 뒤 1 token씩 append하는 방식은 같은 logits와 greedy IDs를 내야 합니다. 다르면 RoPE offset, mask offset, layer별 cache 분리, sequence axis를 점검하세요.</p><pre class=\"lesson-code\"><code>torch.testing.assert_close(uncached_logits[:, -1], cached_logits[:, -1])<br>assert torch.equal(uncached_next_id, cached_next_id)</code></pre><div class=\"task\"><b>실습</b><p>16/128/1024/4096-token prompt에서 uncached와 cached TPOT, peak memory를 비교하세요.</p></div>"]],[["Derive","임의 설정의 cache bytes를 계산한다."],["Build","layer별 preallocated cache를 만든다."],["Verify","cached/uncached logits와 IDs를 비교한다."],["Operate","overflow와 request 종료를 처리한다."]],{title:"Reference code line by line",intro:"append는 새 K/V가 들어갈 slice를 계산하고 storage를 늘리지 않은 채 기록합니다.",lines:[{line:"s = cache.length",explanation:"현재 저장된 token 수이며 다음 write의 시작 index입니다."},{line:"e = s + k_new.size(-2)",explanation:"이번 호출의 새 token 수를 더해 끝 index를 계산합니다."},{line:"cache.k[..., s:e, :].copy_(k_new)",explanation:"모든 batch/head의 sequence slice에 K를 in-place로 복사합니다."},{line:"cache.length = e",explanation:"write가 성공한 뒤에만 valid length를 갱신합니다."},{line:"return cache.k[..., :e, :]",explanation:"유효 token만 attention에 노출합니다."}]});
  attach("kernels","10","18–26 hours","naive attention이 어디에서 HBM traffic을 만드는지 설명하고 online softmax가 왜 같은 결과를 보존하는지 profiler evidence와 함께 제시할 수 있다.",[["IO model","FLOPs보다 bytes 먼저 세기","<p>naive attention은 S=QKᵀ를 만들고 HBM에 쓰고, softmax 결과 P를 다시 쓰고, P를 읽어 PV를 계산합니다. S와 P는 T×T입니다. T=8192에서 head 하나의 FP16 score matrix만 약 128 MiB입니다.</p><p>FlashAttention의 목표는 큰 score/probability matrix를 HBM에 materialize하지 않는 것입니다. Q/K/V tile을 on-chip memory로 가져와 계산하고, 필요한 state만 유지합니다.</p>"],["Online softmax","tile을 합쳐도 정확한 이유","<p>이미 처리한 block의 max를 m, 분모를 l, value 가중합 분자를 acc라고 둡니다. 새 block이 더 큰 max를 보이면 이전 누적값은 옛 기준으로 저장되어 있으므로 rescale해야 합니다.</p><div class=\"equation\">m′ = max(m, max(S<sub>block</sub>))<br>l′ = e<sup>m−m′</sup>l + Σe<sup>Sblock−m′</sup><br>acc′ = e<sup>m−m′</sup>acc + Σe<sup>Sblock−m′</sup>Vblock</div><p>마지막 output은 acc/l입니다. 전체 score를 한 번에 softmax한 결과와 수학적으로 동등하고, floating point 순서 차이만 남습니다.</p>"],["Tiling","tile size가 성능에 미치는 영향","<p>큰 tile은 데이터 재사용을 늘리지만 register/shared-memory 사용량을 높여 resident warp 수를 줄일 수 있습니다. 작은 tile은 occupancy를 높일 수 있지만 HBM traffic과 loop overhead를 늘립니다. 적절한 크기는 GPU, head dimension, sequence length, dtype에 따라 다릅니다.</p><div class=\"task\"><b>실습</b><p>naive path와 optimized SDPA path의 profiler trace를 캡처하세요. kernel time, peak allocation, estimated HBM traffic, end-to-end latency를 같은 표에 기록하세요.</p></div>"],["Benchmarking","kernel 결과와 serving 결과 분리","<p>단일 kernel이 빨라도 scheduler가 GPU를 비워두거나 CPU tokenization이 병목이면 사용자 latency는 변하지 않을 수 있습니다. 동일 [B,H,T,D]만 반복하는 microbenchmark와 요청 arrival/서로 다른 길이를 갖는 serving benchmark를 분리해 보고하세요.</p><div class=\"warning\"><b>정확성:</b><p>output error뿐 아니라 mask, odd sequence length, non-contiguous input, BF16/FP16, fully masked row를 확인하세요.</p></div>"]],[["Trace","naive attention의 T² temporary를 지목한다."],["Derive","online softmax state update를 유도한다."],["Measure","microbenchmark와 end-to-end를 분리한다."],["Explain","IO-aware를 bytes 관점에서 설명한다."]],{title:"Reference code line by line",intro:"이 pseudo-code는 query row가 여러 key/value tile을 지나며 softmax를 안정적으로 누적하는 원리입니다.",lines:[{line:'m, l, acc = -float("inf"), 0.0, 0.0',explanation:"아직 본 score가 없으므로 max는 −∞, 분모와 분자는 0에서 시작합니다."},{line:"tile_m = scores.max()",explanation:"현재 tile 안의 최대 logit입니다."},{line:"new_m = max(m, tile_m)",explanation:"기존 tile과 새 tile을 함께 봤을 때의 기준 max입니다."},{line:"alpha = exp(m - new_m)",explanation:"old max 기준의 이전 누적값을 new max 기준으로 옮기는 비율입니다."},{line:"l = alpha * l + p.sum()",explanation:"softmax 분모의 부분합을 합칩니다."},{line:"acc = alpha * acc + (p[:, None] * values).sum(0)",explanation:"value 가중합 분자도 같은 기준으로 합칩니다."},{line:"out = acc / l",explanation:"모든 tile을 처리한 뒤 한 번만 정규화합니다."}]});

  attach("scheduling","12","22–30 hours","request lifecycle을 명시적으로 모델링하고 static batching과 iteration-level scheduling을 같은 workload에서 공정하게 비교할 수 있다.",[["Lifecycle","요청은 상태를 가진다","<p>요청은 WAITING에서 admission을 기다리고, prompt를 처리하면 PREFILLING, 첫 token 이후 RUNNING(decode), 종료 조건에서 FINISHED가 됩니다. cancellation은 어느 상태에서나 올 수 있고 cache와 stream을 정리해야 합니다.</p><div class=\"equation\">WAITING → PREFILLING → RUNNING → FINISHED<br>             ↘ CANCELLED ↗</div><p>scheduler state와 GPU executor state를 분리해야 policy를 deterministic하게 test할 수 있습니다.</p>"],["Static batching","빈 slot이 생기는 이유","<p>출력 길이 2,9,5 요청을 static batch에 넣으면 9 iteration 동안 세 slot을 예약합니다. 길이 2 요청은 3번째 iteration부터 빈 slot을 남깁니다. continuous batching은 매 iteration 뒤 끝난 요청을 빼고 waiting request를 넣습니다.</p><p>Orca의 핵심은 “요청 전체”가 아니라 “다음 iteration에서 필요한 작업”을 batch로 본다는 점입니다.</p>"],["Token budget","prefill과 decode 균형","<p>긴 prefill은 많은 token budget을 쓰지만 GPU utilization에는 유리할 수 있습니다. decode는 한 token뿐이지만 사용자는 다음 token을 기다립니다. 모든 prefill을 먼저 처리하면 TPOT가 나빠지고, 모든 decode만 우선하면 TTFT가 무한히 커질 수 있습니다.</p><pre class=\"lesson-code\"><code>for req in running:<br>&nbsp;&nbsp;plan.append((req.id, \"decode\", 1))<br>while waiting and token_budget:<br>&nbsp;&nbsp;n = min(req.prompt_remaining, token_budget, chunk)<br>&nbsp;&nbsp;plan.append((req.id, \"prefill\", n))</code></pre><p>chunk는 한 긴 prompt가 batch를 독점하지 못하게 합니다. 작을수록 fairness는 좋아질 수 있지만 scheduling overhead는 늘 수 있습니다.</p>"],["Evaluation","평균 하나로 판단하지 않기","<p>arrival rate, prompt/output length distribution, SLO class를 고정하고 TTFT p50/p95/p99, TPOT p50/p95/p99, tokens/s, goodput, queue length, starvation count를 함께 기록하세요. offline saturated throughput과 online workload 결과는 별도 그래프입니다.</p><div class=\"task\"><b>실습</b><p>site simulator에서 길이와 arrival time을 바꾸며 decode-first와 chunked-prefill policy를 비교하세요. 어떤 요청이 이득과 손해를 보는지 서술하세요.</p></div>"]],[["Model","취소를 포함한 request state machine을 작성한다."],["Simulate","static/continuous scheduler를 동일 workload에 실행한다."],["Policy","decode-first와 chunked prefill을 구현한다."],["Evaluate","tail latency와 goodput으로 trade-off를 설명한다."]],{title:"Reference code line by line",intro:"scheduler는 model forward를 직접 하지 않고 이번 iteration에서 executor가 실행할 작업 계획만 만듭니다.",lines:[{line:"batch = []",explanation:"이번 iteration의 작업 명세를 담는 목록입니다."},{line:"for req in running:",explanation:"이미 첫 token을 받은 요청을 먼저 순회합니다."},{line:'batch.append((req, "decode", 1))',explanation:"요청 하나에 새 token 하나를 할당해 inter-token latency를 보호합니다."},{line:"n = min(req.prompt_remaining, token_budget, 256)",explanation:"남은 prompt, capacity, 최대 chunk 중 가장 작은 값을 선택합니다."},{line:"if n == req.prompt_remaining: waiting.popleft()",explanation:"prompt가 완전히 처리된 요청만 waiting queue에서 제거합니다."}]});

  attach("paged","12","22–32 hours","logical sequence position과 physical KV memory를 분리하고 block table·free list·reference count·copy-on-write를 가진 paged cache simulator를 작성할 수 있다.",[["Motivation","contiguous allocation이 막히는 지점","<p>요청별 최대 output 길이를 미리 contiguous buffer로 잡으면 짧게 끝난 요청의 tail이 낭비됩니다. 여러 길이의 요청이 들어오고 나가면 free bytes 총량은 충분해도 큰 연속 chunk가 없어지는 external fragmentation이 생길 수 있습니다.</p><p>PagedAttention은 KV cache를 fixed-size physical block으로 나누고, sequence별 logical block number → physical block ID table을 둡니다.</p>"],["Address translation","token position을 block으로 바꾸기","<p>token position p는 logical block <code>p // block_size</code>, block 내부 offset <code>p % block_size</code>로 번역됩니다. block table의 해당 entry를 읽으면 실제 physical block ID를 얻습니다.</p><div class=\"equation\">physical block = table[p // block_size]<br>offset = p % block_size</div><p>이 한 단계가 contiguous memory라는 가정을 없애고, kernel이 address translation을 수행하게 합니다.</p>"],["Allocator invariants","free list와 reference count","<table><thead><tr><th>상태</th><th>반드시 참이어야 하는 것</th></tr></thead><tbody><tr><td>free list</td><td>reference count가 0인 block만 들어 있다.</td></tr><tr><td>sequence table</td><td>각 entry는 allocated physical block을 가리킨다.</td></tr><tr><td>append</td><td>마지막 block이 찰 때만 새 block을 얻는다.</td></tr><tr><td>release</td><td>refcount가 0인 block만 free list로 돌아간다.</td></tr></tbody></table><pre class=\"lesson-code\"><code>block = pool.allocate()<br>pool.incref(block)  # shared prefix<br>pool.decref(block)  # release; zero면 free list로</code></pre>"],["Waste and sharing","internal waste와 COW","<p>block size=16인 길이 17 sequence는 두 번째 block에서 15 slot을 아직 쓰지 않습니다. 요청별 마지막 block 낭비는 최대 block_size−1입니다. 작은 block은 waste를 줄이지만 table/allocator overhead를 늘립니다.</p><p>prefix sharing에서 reference count&gt;1인 partial block에 쓰기 전에는 copy-on-write가 필요합니다. 그렇지 않으면 한 요청의 새 token이 다른 요청의 prompt를 오염시킬 수 있습니다.</p><div class=\"task\"><b>실습</b><p>block size 4,8,16,32에서 internal waste, table entries, allocation count를 비교하고 cancellation·double release·allocation failure test를 작성하세요.</p></div>"]],[["Map","token position을 physical block/offset으로 변환한다."],["Manage","free list와 refcount allocator를 구현한다."],["Share","prefix sharing과 COW를 test한다."],["Measure","block-size trade-off를 그래프로 보인다."]],{title:"Reference code line by line",intro:"BlockTable은 sequence의 logical 주소를 pool의 physical 주소로 바꾸는 작은 page table입니다.",lines:[{line:"offset = self.length % self.block_size",explanation:"다음 token이 마지막 block의 몇 번째 slot에 들어갈지 계산합니다."},{line:"if offset == 0:",explanation:"새 logical block의 첫 token일 때만 새 physical block이 필요합니다."},{line:"self.blocks.append(self.pool.allocate())",explanation:"free pool에서 block ID를 받아 logical table 끝에 기록합니다."},{line:"physical = self.blocks[self.length // self.block_size]",explanation:"logical token index에서 logical block index를 구해 physical ID를 찾습니다."},{line:"self.pool.decref(block)",explanation:"sequence 종료 시 reference count를 줄이며 0이 된 block만 재사용됩니다."}]});

  attach("production","14","30+ hours","API부터 streamed token까지의 request path를 추적하고 quality·latency·throughput·memory를 함께 측정하는 재현 가능한 serving experiment를 설계할 수 있다.",[["System boundary","model.forward 밖에 있는 것","<p>실제 serving은 model.forward 하나보다 큽니다. API가 validation/cancellation을 받고, tokenizer가 text를 IDs로 만들고, scheduler가 admission을 결정하고, executor가 GPU batch를 실행하고, detokenizer가 token을 stream으로 바꿉니다.</p><div class=\"equation\">request → validate → tokenize → queue → schedule → prefill/decode → sample → detokenize → stream → finalize</div><p>각 단계 timestamp가 있어야 TTFT가 queueing, tokenization, GPU prefill 중 어디에서 생겼는지 구분할 수 있습니다.</p>"],["Parallelism","capacity에도 비용이 있다","<table><thead><tr><th>방법</th><th>분할 대상</th><th>새 비용</th></tr></thead><tbody><tr><td>Tensor parallel</td><td>한 layer weight/activation</td><td>all-reduce/all-gather</td></tr><tr><td>Pipeline parallel</td><td>layer stage</td><td>bubble, stage imbalance</td></tr><tr><td>Data parallel</td><td>독립 request batch</td><td>load balance, cache locality</td></tr><tr><td>Disaggregated prefill/decode</td><td>phase별 worker</td><td>KV transfer, routing</td></tr></tbody></table><p>첫 질문은 GPU 수가 아니라 어떤 resource가 먼저 포화되는가입니다. prefill은 compute, decode는 KV bandwidth, distributed run은 communication이 병목일 수 있습니다.</p>"],["Quantization","memory reduction과 quality를 함께 보기","<p>weight-only INT8/INT4, activation quantization, KV quantization은 bytes를 줄이는 방식과 error source가 다릅니다. “memory가 줄었다”와 “goodput이 올랐다”는 다른 주장입니다. 같은 prompt, sampling seed, quality metric, hardware, batch policy에서 비교해야 합니다.</p><div class=\"task\"><b>실험 카드</b><p>각 configuration에 model, quantization, calibration, workload, quality metric, TTFT/TPOT percentiles, tokens/s, peak memory, failure rate를 한 행으로 기록하세요.</p></div>"],["Research method","논문으로 가는 실험","<p>좋은 systems paper는 “우리 방법이 빠르다”가 아니라 특정 workload에서 기존 policy의 관찰 가능한 실패를 규정합니다. 예: long-prefill admission이 interactive decode의 p99 TPOT를 악화시키는가?</p><div class=\"equation\">Workload W에서 policy P가 failure F를 만드는 원인 M을 측정한다.<br>방법 X가 M을 바꿔 metric Y를 개선하며 constraint Z를 지킨다는 가설을 검증한다.</div><p>baseline, ablation, sensitivity analysis, negative result, confidence interval을 실험 전에 계획하세요.</p>"]],[["Trace","request lifecycle trace를 수집하고 병목을 분류한다."],["Prototype","scheduler/cache policy를 바꿀 수 있는 engine을 만든다."],["Benchmark","online workload에서 TTFT, TPOT, goodput, memory를 보고한다."],["Paper","falsifiable claim, baseline, ablation, limitation을 작성한다."]],{title:"Reference code line by line",intro:"metrics object는 계산된 평균이 아니라 원시 timestamp를 보관해 tail analysis와 정의 변경을 가능하게 합니다.",lines:[{line:"arrived_at: float",explanation:"사용자가 요청을 보낸 시각이며 TTFT와 end-to-end의 시작점입니다."},{line:"admitted_at: float | None = None",explanation:"scheduler가 GPU capacity를 주기로 한 시각입니다. arrival과의 차이는 queueing delay입니다."},{line:"first_token_at: float | None = None",explanation:"첫 streamed token이 실제로 전달된 시각입니다. prefill 완료와 같다고 가정하면 안 됩니다."},{line:"token_times: list[float]",explanation:"각 token timestamp를 남겨 p95 TPOT 같은 분포를 나중에 계산합니다."},{line:"gaps = np.diff(self.token_times)",explanation:"연속 output token 사이 gap을 구합니다. 첫 token 이전 시간은 TTFT에 속합니다."}]});
  byId.transformer.longform = byId.transformer.longform.replace(
    "rms = x.pow(2).mean(dim=-1, keepdim=True).add(eps).rsqrt()<br>return x * rms * weight",
    "work = x.float()<br>rms_inv = work.pow(2).mean(dim=-1, keepdim=True).add(eps).rsqrt()<br>return (work * rms_inv).to(x.dtype) * weight"
  ).replace(
    "<code>keepdim=True</code>가 없으면 [B,T] RMS를 [B,T,d] x의 마지막 axis에 broadcast할 수 없습니다.",
    "<code>float()</code>는 square와 reduction을 FP32에서 수행해 저정밀 overflow/rounding 위험을 줄입니다. <code>keepdim=True</code>가 없으면 [B,T] RMS를 [B,T,d] x의 마지막 axis에 broadcast할 수 없습니다. 실제 fused kernel의 accumulation 방식은 구현별로 확인해야 합니다."
  );
  byId.multihead.longform = byId.multihead.longform.replace(
    "H=32,Hkv=8인 GQA의 KV cache payload는 MHA의 1/4입니다.",
    "Layer 수, stored token 수, head dimension, dtype, batch가 같다는 조건에서 H=32,Hkv=8인 GQA의 KV payload는 MHA의 1/4입니다."
  );
  byId.kvcache.longform = byId.kvcache.longform.replace(
    "이 값은 allocator metadata, alignment, workspace, model weights를 포함하지 않습니다.",
    "모든 sequence가 같은 stored-token 길이를 가질 때의 식입니다. 길이가 다르면 active_sequences를 곱하지 말고 sequence별 stored token 수를 합산해야 합니다. allocator metadata, alignment, block table, workspace, model weights는 포함하지 않습니다."
  );
  byId.scheduling.walkthrough = {title:"Reference code line by line",intro:"이 함수는 실행 전 상태를 바꾸지 않고 이번 iteration의 작업 계획만 반환합니다. 실제 request 전이는 executor 성공 뒤 별도 단계에서 처리해야 합니다.",lines:[{line:"plan = []",explanation:"이번 iteration의 immutable work description을 담을 목록입니다."},{line:"for req in running:",explanation:"이미 prefill을 끝낸 decode 요청부터 순회합니다."},{line:'plan.append((req.id, "decode", 1))',explanation:"각 running request에 새 token 하나를 배정합니다."},{line:"for req in waiting:",explanation:"남은 token budget을 waiting prompt에 사용합니다. 이 loop 자체는 queue를 pop하지 않습니다."},{line:"n = min(req.prompt_remaining, token_budget, chunk_size)",explanation:"남은 prompt, 남은 budget, 최대 chunk 중 가장 작은 값을 계획합니다."},{line:"return plan",explanation:"GPU 실행 성공 뒤 별도 state-transition 단계가 prompt_remaining, queue, running set을 갱신해야 합니다."}]};
})();
